// Real weather from OpenWeatherMap (never generated by AI): current conditions and the next days.
// The place is resolved with the country code when known, so "Gran Canaria, ES" never lands on a
// homonym elsewhere. Advice is returned as codes; the app turns them into text in the user's language.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuth } from "../_shared/require-auth.ts";
import { checkRateLimit, rateLimitResponse } from "../_shared/rate-limit.ts";
import { lookupPlace } from "../_shared/place-lookup.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

// Legacy French advice, kept for older screens that still read `advice`.
const ADVICE_FR: Record<string, string> = {
  cold: "Prévois des vêtements chauds : températures fraîches prévues",
  mild: "Prévois un pull léger : nuits fraîches possibles",
  hot: "Hydrate-toi régulièrement : fortes chaleurs prévues",
  humid: "Privilégie des vêtements respirants : humidité élevée",
  windy: "Prévois une veste coupe-vent : vent soutenu prévu",
  rain: "Prévois un imperméable : pluie attendue",
  snow: "Prévois des bottes imperméables et des couches chaudes",
  clouds: "Temps variable : prévois des couches superposables",
  fine: "Conditions clémentes : vêtements légers recommandés",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  const auth = await requireAuth(req, corsHeaders);
  if (auth instanceof Response) return auth;
  const rl = rateLimitResponse(checkRateLimit({ key: "weather", subject: auth.userId, limit: 30, windowMs: 60_000 }), corsHeaders);
  if (rl) return rl;

  try {
    const key = Deno.env.get("OPENWEATHER_API_KEY");
    if (!key) return json({ fallback: true, error: "missing_key", advice: [] });

    const body = await req.json().catch(() => ({}));
    const city = typeof body.city === "string" ? body.city.trim().slice(0, 80) : "";
    const country = typeof body.countryCode === "string" && /^[A-Za-z]{2}$/.test(body.countryCode) ? body.countryCode.toUpperCase() : "";
    const lang = body.lang === "en" || body.locale === "en" ? "en" : "fr";
    let lat = typeof body.lat === "number" ? body.lat : NaN;
    let lon = typeof body.lon === "number" ? body.lon : NaN;
    let place: { name: string; country: string; state: string } | null = null;

    if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
      if (city.length < 2) return json({ error: "city_required" }, 400);
      // Same place lookup as the seasonal averages, so both blocks describe the same spot.
      const p = await lookupPlace(city, country, lang);
      if (!p) return json({ fallback: true, error: "city_not_found", advice: [] });
      lat = p.latitude; lon = p.longitude;
      place = { name: p.name, country: p.countryCode, state: p.region };
    }

    const base = `lat=${lat}&lon=${lon}&units=metric&lang=${lang}&appid=${key}`;
    const [curRes, fcRes] = await Promise.all([
      fetch(`https://api.openweathermap.org/data/2.5/weather?${base}`),
      fetch(`https://api.openweathermap.org/data/2.5/forecast?${base}`),
    ]);
    const data = await curRes.json();
    if (!curRes.ok) {
      console.warn(`OpenWeather ${curRes.status}:`, data);
      return json({ fallback: true, error: curRes.status === 404 ? "city_not_found" : `api_error_${curRes.status}`, advice: [] });
    }

    const temp = Math.round(data.main.temp);
    const feelsLike = Math.round(data.main.feels_like);
    const humidity = data.main.humidity;
    const wind = Math.round((data.wind?.speed ?? 0) * 3.6); // m/s → km/h
    const main = String(data.weather?.[0]?.main || "");
    const conditions = data.weather?.[0]?.description || "—";
    const icon = data.weather?.[0]?.icon || "01d";
    const tz = Number(data.timezone) || 0; // seconds from UTC at the place

    // Next days: min/max and the most frequent condition, in the place's local days.
    const forecast: Array<{ date: string; tmin: number; tmax: number; main: string; description: string; icon: string }> = [];
    if (fcRes.ok) {
      const fc = await fcRes.json();
      const byDay = new Map<string, { min: number; max: number; counts: Map<string, { n: number; description: string; icon: string }> }>();
      for (const it of fc.list || []) {
        const day = new Date((it.dt + tz) * 1000).toISOString().slice(0, 10);
        const d = byDay.get(day) || { min: Infinity, max: -Infinity, counts: new Map() };
        d.min = Math.min(d.min, it.main.temp_min);
        d.max = Math.max(d.max, it.main.temp_max);
        const w = it.weather?.[0];
        if (w) {
          const c = d.counts.get(w.main) || { n: 0, description: w.description, icon: w.icon };
          c.n++; d.counts.set(w.main, c);
        }
        byDay.set(day, d);
      }
      const today = new Date((Math.floor(Date.now() / 1000) + tz) * 1000).toISOString().slice(0, 10);
      for (const [date, d] of byDay) {
        if (date <= today) continue;
        const top = [...d.counts.entries()].sort((a, b) => b[1].n - a[1].n)[0];
        forecast.push({ date, tmin: Math.round(d.min), tmax: Math.round(d.max), main: top?.[0] || "", description: top?.[1].description || "", icon: top?.[1].icon || "01d" });
        if (forecast.length >= 4) break;
      }
    }

    const codes: string[] = [];
    if (temp < 15) codes.push("cold");
    if (temp >= 15 && temp < 22) codes.push("mild");
    if (temp >= 30) codes.push("hot");
    if (humidity > 70) codes.push("humid");
    if (wind > 30) codes.push("windy");
    if (["Rain", "Drizzle", "Thunderstorm"].includes(main)) codes.push("rain");
    if (main === "Snow") codes.push("snow");
    if (main === "Clouds") codes.push("clouds");
    if (!codes.length) codes.push("fine");

    return json({
      temperature: `${temp}°C`,
      feelsLike: `${feelsLike}°C`,
      humidity: `${humidity}%`,
      wind: `${wind} km/h`,
      conditions,
      icon,
      advice: codes.map((c) => ADVICE_FR[c]),
      // Structured data for the Valise
      current: { temp, feelsLike, humidity, windKmh: wind, main, description: conditions, icon, observedAt: new Date((data.dt || 0) * 1000).toISOString(), timezoneOffset: tz },
      forecast,
      adviceCodes: codes,
      place: place ?? { name: data.name || city, country: data.sys?.country || country, state: "" },
      source: { name: "OpenWeatherMap", url: "https://openweathermap.org/" },
      fetchedAt: new Date().toISOString(),
    });
  } catch (error: unknown) {
    console.error("Weather API error:", error);
    return json({ fallback: true, error: "unavailable", advice: [] });
  }
});
